interactive.css:
.mytable1, .mytable2 {
  border-collapse: collapse;
  margin: 10px;
  position: absolute;
}
.mytable2 {
  border: 3px solid #888;
  left: 30px;
  top: 30px;
  transform: rotate(10deg);
}
.mytable1 td {
  border: 1px solid #888;
}
.mytable1 td, .mytable2 td {
  width: 50px;
  height: 50px;
  text-align: center;
  font-size: 32px;
}
.mytable2 td:not(.black) {
    background-color: rgba(0, 0, 0, 0.8);
}
